import{_ as t,o as l,c as i,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"دستاویز کا ورژن اور دیکھ بھال کی ہدایات","description":"","frontmatter":{},"headers":[],"relativePath":"ur/99-文档版本与维护说明.md","filePath":"ur/99-文档版本与维护说明.md","lastUpdated":null}'),r={name:"ur/99-文档版本与维护说明.md"};function o(h,a,d,n,s,u){return l(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="دستاویز-کا-ورژن-اور-دیکھ-بھال-کی-ہدایات" tabindex="-1">دستاویز کا ورژن اور دیکھ بھال کی ہدایات <a class="header-anchor" href="#دستاویز-کا-ورژن-اور-دیکھ-بھال-کی-ہدایات" aria-label="Permalink to &quot;دستاویز کا ورژن اور دیکھ بھال کی ہدایات&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>99</td></tr><tr><td>ماڈیول</td><td>ضمیمے اور حوالہ جاتی مواد</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>ورژن کا انتظام، دیکھ بھال کی ہدایات، دستاویز کے ضوابط، اپ ڈیٹ لاگ، ترتیب کی دیکھ بھال</td></tr></tbody></table><h2 id="_1-دستاویز-کے-نظام-کا-خلاصہ" tabindex="-1">1. دستاویز کے نظام کا خلاصہ <a class="header-anchor" href="#_1-دستاویز-کے-نظام-کا-خلاصہ" aria-label="Permalink to &quot;1. دستاویز کے نظام کا خلاصہ&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب کے ترتیب کا نظام 100 مارک ڈاؤن دستاویزات پر مشتمل ہے، جن کی تعداد 00 سے 99 تک ہے، دس ماڈیولز میں تقسیم ہے، ہر ماڈیول میں 10 دستاویزات ہیں۔ دستاویز کا نظام SPEC.md (دستاویز بنانے کے ضوابط) کو سخت پابندی کے طور پر قبول کرتا ہے، 00-ہینگیوانژو کائنات کا جائزہ کو عمومی رہنما کے طور پر قبول کرتا ہے، ہر ماڈیول کے دستاویزات مختلف جہتوں سے تفصیل سے وسیع ہوتے ہیں، اور آخر میں 90-99 ضمیمہ دستاویزات انڈیکس، خلاصہ اور تنظیم کا کام کرتی ہیں۔ پورا دستاویز نظام ایک منطقی طور پر خود مطابقت رکھنے والا، سطحوں والا، باہمی حوالہ دینے والا مکمل ترتیب علم خانہ بناتا ہے۔</p><p>دستاویز کے نظام کا ڈیزائن &quot;ماڈیولر، ساختہ، قابل توسیع&quot; تین اصولوں پر عمل کرتا ہے۔ ماڈیولر کا مطلب ہے کہ ہر دستاویز ایک مخصوص موضوع پر مرکوز ہے اور آزادانہ طور پر مکمل ہے۔ ساختہ کا مطلب ہے کہ تمام دستاویزات یکساں فارمیٹ کے ضوابط پر عمل کرتے ہیں، پڑھنے اور تلاش میں سہولت فراہم کرتے ہیں۔ قابل توسیع کا مطلب ہے کہ دستاویز کا نظام توسیع کے لیے کافی جگہ محفوظ رکھتا ہے، موجودہ دستاویزات میں ترمیم اور نئے مواد کے اضافے کے ذریعے مسلسل ترتیب کو بہتر بنا سکتا ہے۔</p><h2 id="_2-ورژن-نمبر-کے-قواعد" tabindex="-1">2. ورژن نمبر کے قواعد <a class="header-anchor" href="#_2-ورژن-نمبر-کے-قواعد" aria-label="Permalink to &quot;2. ورژن نمبر کے قواعد&quot;">​</a></h2><p>دستاویز کا نظام &quot;مرکزی ورژن نمبر.ثانوی ورژن نمبر.ترمیم نمبر&quot; کی تین سطحی ورژن نمبر کے قاعدے کو اپناتا ہے:</p><table tabindex="0"><thead><tr><th>ورژن کی سطح</th><th>نمبر کے قواعد</th><th>متحرک حالت</th><th>مثال</th></tr></thead><tbody><tr><td>مرکزی ورژن نمبر</td><td>1 سے بڑھتا ہے</td><td>دستاویز کے نظام میں بڑی ساختی تبدیلی، جیسے ماڈیول کی دوبارہ تقسیم، بنیادی ترتیب کی تبدیلی</td><td>v1.0 → v2.0</td></tr><tr><td>ثانوی ورژن نمبر</td><td>0 سے بڑھتا ہے</td><td>کسی دستاویز کے بنیادی مواد میں بنیادی ترمیم، یا اہم ترتیب مواد کا اضافہ</td><td>v1.0 → v1.1</td></tr><tr><td>ترمیم نمبر</td><td>0 سے بڑھتا ہے</td><td>دستاویز کے متن کی اصلاح، فارمیٹ کی ایڈجسٹمنٹ، اصطلاحات کا یکجا کرنا وغیرہ غیر بنیادی تبدیلیاں</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>موجودہ دستاویز کے نظام کا مجموعی ورژن v1.0 ہے، یعنی پہلا مکمل جاری کردہ ورژن۔ ہر دستاویز اپنے دستاویز معلومات بلاک میں اپنا ورژن نمبر ریکارڈ کرتا ہے، اور دستاویز کے نظام کا مجموعی ورژن نمبر اس دستاویز میں یکجا طور پر ریکارڈ کیا جاتا ہے۔</p><h2 id="_3-دستاویز-فارمیٹ-کے-ضوابط-کا-جائزہ" tabindex="-1">3. دستاویز فارمیٹ کے ضوابط کا جائزہ <a class="header-anchor" href="#_3-دستاویز-فارمیٹ-کے-ضوابط-کا-جائزہ" aria-label="Permalink to &quot;3. دستاویز فارمیٹ کے ضوابط کا جائزہ&quot;">​</a></h2><p>تمام دستاویزات کو درج ذیل یکساں فارمیٹ کے ضوابط پر عمل کرنا ہوگا (تفصیلی ضوابط SPEC.md دیکھیں):</p><h3 id="_3-1-فائل-کا-نام" tabindex="-1">3.1 فائل کا نام <a class="header-anchor" href="#_3-1-فائل-کا-نام" aria-label="Permalink to &quot;3.1 فائل کا نام&quot;">​</a></h3><p>فائل نام کا فارمیٹ <code>XX-دستاویز کا عنوان.md</code> ہے، جہاں XX 00 سے 99 تک کا دو ہندسوں کا نمبر ہے، عنوان چینی زبان میں ہے، خالی جگہ کے بغیر۔</p><h3 id="_3-2-دستاویز-کا-ڈھانچہ" tabindex="-1">3.2 دستاویز کا ڈھانچہ <a class="header-anchor" href="#_3-2-دستاویز-کا-ڈھانچہ" aria-label="Permalink to &quot;3.2 دستاویز کا ڈھانچہ&quot;">​</a></h3><p>ہر دستاویز میں درج ذیل ڈھانچے کے عناصر ضرور شامل ہونے چاہئیں:</p><ol><li><strong>پہلی سطح کا عنوان</strong>: دستاویز کا عنوان (فائل نام کے ساتھ مطابقت رکھتا ہے)</li><li><strong>دستاویز معلومات بلاک</strong>: نمبر، ماڈیول، بنیادی کلیدی الفاظ (3-5) کی جدول</li><li><strong>اصل متن</strong>: کم از کم 3 دوسری سطح کے عنوان والے ابواب، فہرستوں، جدولوں جیسے ساختہ عناصر کا استعمال</li><li><strong>اختتامیہ</strong>: مختصر خلاصہ پیراگراف</li><li><strong>متعلقہ دستاویزات</strong>: 2-3 متعلقہ دستاویزات کے نمبر اور نام درج کرنا</li></ol><h3 id="_3-3-الفاظ-کی-تعداد-کی-ضرورت" tabindex="-1">3.3 الفاظ کی تعداد کی ضرورت <a class="header-anchor" href="#_3-3-الفاظ-کی-تعداد-کی-ضرورت" aria-label="Permalink to &quot;3.3 الفاظ کی تعداد کی ضرورت&quot;">​</a></h3><p>ہر دستاویز کا اصل متن 800 حروف سے کم نہیں ہونا چاہیے (عنوان اور میٹا معلومات کے علاوہ)۔</p><h3 id="_3-4-تحریر-کا-انداز" tabindex="-1">3.4 تحریر کا انداز <a class="header-anchor" href="#_3-4-تحریر-کا-انداز" aria-label="Permalink to &quot;3.4 تحریر کا انداز&quot;">​</a></h3><ul><li>سنجیدہ، منظم ترتیب دستاویز کا انداز، انسائیکلوپیڈیا/ترتیب مجموعے کی طرح</li><li>&quot;ہینگیوانژو&quot; &quot;اینکر&quot; &quot;سمبیوسس&quot; جیسی یکساں اصطلاحات کا استعمال</li><li>تکمیلی نئی ترتیبات کو موجودہ ترتیبات کے ساتھ منطقی طور پر خود مطابقت رکھنا چاہیے، &quot;حقیقت پر مبنی، قوانین کی بہتری&quot; کے اصول کے مطابق</li></ul><h2 id="_4-دیکھ-بھال-کی-تنظیم-اور-ذمہ-داریاں" tabindex="-1">4. دیکھ بھال کی تنظیم اور ذمہ داریاں <a class="header-anchor" href="#_4-دیکھ-بھال-کی-تنظیم-اور-ذمہ-داریاں" aria-label="Permalink to &quot;4. دیکھ بھال کی تنظیم اور ذمہ داریاں&quot;">​</a></h2><h3 id="_4-1-ترتیب-دیکھ-بھال-کمیٹی" tabindex="-1">4.1 ترتیب دیکھ بھال کمیٹی <a class="header-anchor" href="#_4-1-ترتیب-دیکھ-بھال-کمیٹی" aria-label="Permalink to &quot;4.1 ترتیب دیکھ بھال کمیٹی&quot;">​</a></h3><p>ترتیب دیکھ بھال کمیٹی دستاویز کے نظام کی اعلیٰ ترین دیکھ بھال کی ادارہ ہے، جس میں تجربہ کار ترتیب تخلیق کار، منطقی تصدیق کے ماہر اور صارف کے نمائندے شامل ہیں۔ اس کی بنیادی ذمہ داریاں شامل ہیں:</p><ul><li>دستاویز کے نظام کے مجموعی ڈھانچے اور بڑے ترمیم کے منصوبوں کی منظوری دینا</li><li>بڑی ترتیب کی تبدیلیوں کی تصدیق کرنا، بنیادی ترتیب کے ساتھ مطابقت کو یقینی بنانا</li><li>ترتیب کے تنازعات کا فیصلہ کرنا، مستند تشریح فراہم کرنا</li><li>باقاعدگی سے مکمل ترتیب مطابقت کی خود جانچ کا انعقاد کرنا</li><li>دستاویز کے نظام کے مجموعی ورژن اپ ڈیٹ شائع کرنا</li></ul><h3 id="_4-2-ماڈیول-دیکھ-بھال-کرنے-والا" tabindex="-1">4.2 ماڈیول دیکھ بھال کرنے والا <a class="header-anchor" href="#_4-2-ماڈیول-دیکھ-بھال-کرنے-والا" aria-label="Permalink to &quot;4.2 ماڈیول دیکھ بھال کرنے والا&quot;">​</a></h3><p>ہر ماڈیول میں ایک ماڈیول دیکھ بھال کرنے والا مقرر کیا جاتا ہے، جس کی ذمہ داری اس ماڈیول کے 10 دستاویزات کی روزمرہ دیکھ بھال ہے۔ اس کی ذمہ داریاں شامل ہیں:</p><ul><li>ماڈیول کے اندر دستاویزات کی ترتیب مطابقت کو ٹریک کرنا</li><li>ماڈیول کے اندر دستاویزات کی ترمیم کی درخواست کی تصدیق کرنا</li><li>ماڈیول کے اندر دستاویزات کے درمیان باہمی حوالے کو مربوط کرنا</li><li>ماڈیول کے مواد کے بارے میں صارفین کے رائے اور تجاویز اکٹھا کرنا</li><li>باقاعدگی سے ترتیب دیکھ بھال کمیٹی کو ماڈیول کی دیکھ بھال کی صورتحال کی رپورٹ کرنا</li></ul><h3 id="_4-3-دستاویز-تخلیق-کار" tabindex="-1">4.3 دستاویز تخلیق کار <a class="header-anchor" href="#_4-3-دستاویز-تخلیق-کار" aria-label="Permalink to &quot;4.3 دستاویز تخلیق کار&quot;">​</a></h3><p>کوئی بھی اہلیت رکھنے والا تخلیق کار دستاویزات کی تخلیق اور ترمیم میں حصہ لے سکتا ہے۔ تخلیق کار کی ذمہ داریاں شامل ہیں:</p><ul><li>فارمیٹ کے ضوابط کے مطابق دستاویز بنانا یا ترمیم کرنا</li><li>اس بات کو یقینی بنانا کہ تخلیقی مواد ترتیب کے تضاد کی خود جانچ کی جدول کی جانچ پاس کرے</li><li>ترمیم جمع کرواتے وقت تفصیلی ترمیم کی وضاحت منسلک کرنا</li><li>دیکھ بھال کرنے والے اور کمیٹی کے تصدیقی کام میں تعاون کرنا</li></ul><h2 id="_5-ترمیم-کا-عمل" tabindex="-1">5. ترمیم کا عمل <a class="header-anchor" href="#_5-ترمیم-کا-عمل" aria-label="Permalink to &quot;5. ترمیم کا عمل&quot;">​</a></h2><h3 id="_5-1-عام-ترمیم-کا-عمل" tabindex="-1">5.1 عام ترمیم کا عمل <a class="header-anchor" href="#_5-1-عام-ترمیم-کا-عمل" aria-label="Permalink to &quot;5.1 عام ترمیم کا عمل&quot;">​</a></h3><ol><li><strong>درخواست جمع کروانا</strong>: تخلیق کار ماڈیول دیکھ بھال کرنے والے کو ترمیم کی درخواست جمع کرواتا ہے، جس میں ترمیم شدہ دستاویز کا نمبر، ترمیم شدہ مواد کی تفصیل اور ترمیم کی وجہ شامل ہوتی ہے۔</li><li><strong>ماڈیول کی تصدیق</strong>: ماڈیول دیکھ بھال کرنے والا ترمیم شدہ مواد کی تصدیق کرتا ہے، خاص طور پر فارمیٹ کے ضوابط اور ماڈیول کے اندر مطابقت کی جانچ کرتا ہے۔ تصدیق پاس کرنے کے بعد ترتیب دیکھ بھال کمیٹی کو جمع کرواتا ہے۔</li><li><strong>کمیٹی کی منظوری</strong>: ترتیب دیکھ بھال کمیٹی ترمیم شدہ مواد کی حتمی منظوری دیتی ہے، خاص طور پر ماڈیولز کے درمیان مطابقت اور بنیادی ترتیب کی مطابقت کی جانچ کرتی ہے۔</li><li><strong>ترمیم پر عمل کرنا</strong>: منظوری پاس کرنے کے بعد، ماڈیول دیکھ بھال کرنے والا یا اصل تخلیق کار دستاویز کی ترمیم پر عمل کرتا ہے۔</li><li><strong>ورژن اپ ڈیٹ</strong>: ترمیم مکمل ہونے کے بعد، دستاویز کا ورژن نمبر اپ ڈیٹ کیا جاتا ہے، اور اس دستاویز کے اپ ڈیٹ لاگ میں ریکارڈ کیا جاتا ہے۔</li><li><strong>متعلقہ ہم آہنگی</strong>: اگر ترمیم شدہ مواد دوسرے دستاویزات کو متاثر کرتا ہے، تو متعلقہ دستاویزات کو ہم آہنگی کے ساتھ ترمیم کرنا ہوگا۔</li></ol><h3 id="_5-2-فوری-ترمیم-کا-عمل" tabindex="-1">5.2 فوری ترمیم کا عمل <a class="header-anchor" href="#_5-2-فوری-ترمیم-کا-عمل" aria-label="Permalink to &quot;5.2 فوری ترمیم کا عمل&quot;">​</a></h3><p>شدید ترتیب کے تضاد یا غلطی کی دریافت ہونے والی فوری صورتحال کے لیے، فوری ترمیم کا عمل شروع کیا جا سکتا ہے:</p><ol><li><strong>فوری رپورٹ</strong>: دریافت کرنے والا فوری طور پر ترتیب دیکھ بھال کمیٹی کو مسئلہ کی رپورٹ کرتا ہے۔</li><li><strong>فوری منظوری</strong>: کمیٹی 24 گھنٹوں میں فوری منظوری مکمل کرتی ہے اور ترمیم کا منصوبہ فراہم کرتی ہے۔</li><li><strong>ترمیم پر عمل کرنا</strong>: مخصوص شخص کو مقرر کرکے فوری طور پر ترمیم پر عمل کیا جاتا ہے۔</li><li><strong>بعد میں ریکارڈ</strong>: ترمیم مکمل ہونے کے بعد ترمیم کی درخواست اور تصدیق کا ریکارڈ بعد میں پورا کیا جاتا ہے۔</li></ol><h3 id="_5-3-باقاعدگی-سے-مکمل-ترمیم" tabindex="-1">5.3 باقاعدگی سے مکمل ترمیم <a class="header-anchor" href="#_5-3-باقاعدگی-سے-مکمل-ترمیم" aria-label="Permalink to &quot;5.3 باقاعدگی سے مکمل ترمیم&quot;">​</a></h3><p>ترتیب دیکھ بھال کمیٹی ہر سال ایک بار مکمل دستاویز نظام کی ترمیم کا انعقاد کرتی ہے، جس میں شامل ہیں:</p><ul><li>مکمل ترتیب مطابقت کی خود جانچ</li><li>صارفین کے رائے کا مرکزی پروسیسنگ</li><li>اصطلاحات کے نظام کا یکجا کرنا اور اپ ڈیٹ کرنا</li><li>انڈیکس دستاویزات کی ہم آہنگی کے ساتھ اپ ڈیٹ</li><li>دستاویز فارمیٹ کی یکجا جانچ اور اصلاح</li></ul><h2 id="_6-اپ-ڈیٹ-لاگ" tabindex="-1">6. اپ ڈیٹ لاگ <a class="header-anchor" href="#_6-اپ-ڈیٹ-لاگ" aria-label="Permalink to &quot;6. اپ ڈیٹ لاگ&quot;">​</a></h2><h3 id="v1-0-پہلا-مکمل-اشاعت" tabindex="-1">v1.0 (پہلا مکمل اشاعت) <a class="header-anchor" href="#v1-0-پہلا-مکمل-اشاعت" aria-label="Permalink to &quot;v1.0 (پہلا مکمل اشاعت)&quot;">​</a></h3><ul><li>تمام 100 دستاویزات کی تخلیق اور اشاعت مکمل</li><li>دستاویز کے نظام کا مکمل ڈھانچہ اور فارمیٹ کے ضوابط قائم</li><li>دس ماڈیولز کے مواد کی کوریج مکمل</li><li>ضمیمہ انڈیکس نظام قائم (اصطلاحات کا لغت، نظام کا انڈیکس، قانونی انڈیکس، کرونیکل، تمام نسلوں کی فہرست، افراد اور تنظیمیں، FAQ، خود جانچ کی جدول، توسیعی تجاویز، ورژن کی ہدایات)</li></ul><h3 id="بعد-کے-ورژن-اپ-ڈیٹ-ریکارڈ-کا-علاقہ" tabindex="-1">بعد کے ورژن اپ ڈیٹ ریکارڈ کا علاقہ <a class="header-anchor" href="#بعد-کے-ورژن-اپ-ڈیٹ-ریکارڈ-کا-علاقہ" aria-label="Permalink to &quot;بعد کے ورژن اپ ڈیٹ ریکارڈ کا علاقہ&quot;">​</a></h3><p>(بعد کے ورژن کے اپ ڈیٹ مواد یہاں شامل کیے جائیں گے، جس میں ورژن نمبر، اشاعت کی تاریخ، بنیادی اپ ڈیٹ مواد کا خلاصہ شامل ہوگا)</p><h2 id="_7-دستاویز-کے-حوالے-اور-باہمی-حوالے-کے-ضوابط" tabindex="-1">7. دستاویز کے حوالے اور باہمی حوالے کے ضوابط <a class="header-anchor" href="#_7-دستاویز-کے-حوالے-اور-باہمی-حوالے-کے-ضوابط" aria-label="Permalink to &quot;7. دستاویز کے حوالے اور باہمی حوالے کے ضوابط&quot;">​</a></h2><h3 id="_7-1-اندرونی-حوالہ" tabindex="-1">7.1 اندرونی حوالہ <a class="header-anchor" href="#_7-1-اندرونی-حوالہ" aria-label="Permalink to &quot;7.1 اندرونی حوالہ&quot;">​</a></h3><p>دستاویزات کے درمیان باہمی حوالے &quot;دستاویز نمبر-دستاویز کا عنوان&quot; فارمیٹ استعمال کرتے ہیں، مثال کے طور پر &quot;دستاویز 84《آثار قدیمہ کے پروٹوکول کا عمومی پروگرام》دیکھیں&quot;۔ حوالہ دیتے وقت اس بات کو یقینی بنانا ہوگا کہ حوالہ دیا گیا دستاویز واقعی موجود ہے اور نمبر اور عنوان درست ہے۔</p><h3 id="_7-2-اصطلاحات-کا-حوالہ" tabindex="-1">7.2 اصطلاحات کا حوالہ <a class="header-anchor" href="#_7-2-اصطلاحات-کا-حوالہ" aria-label="Permalink to &quot;7.2 اصطلاحات کا حوالہ&quot;">​</a></h3><p>کسی بنیادی اصطلاح کو پہلی بار استعمال کرتے وقت، دستاویز 90《اصطلاحات کا لغت》میں متعلقہ مدخل دیکھیں بتا سکتے ہیں۔ بعد میں ایک ہی اصطلاح استعمال کرتے وقت دہرا کر بتانے کی ضرورت نہیں ہے۔</p><h3 id="_7-3-بیرونی-حوالہ" tabindex="-1">7.3 بیرونی حوالہ <a class="header-anchor" href="#_7-3-بیرونی-حوالہ" aria-label="Permalink to &quot;7.3 بیرونی حوالہ&quot;">​</a></h3><p>اگر ترتیب کے نظام سے باہر حقیقی مواد یا خیالی کاموں کا حوالہ دینا ہو تو ذریعہ بتانا ہوگا، اور واضح طور پر بتانا ہوگا کہ یہ حوالہ &quot;حقیقت پر مبنی&quot; اصول کے تحت حوالہ مواد ہے، یہ ترتیب کے نظام کی اس کے مواد کی مکمل قبولیت کی نمائندگی نہیں کرتا۔</p><h2 id="_8-معیار-کی-ضمانت-کا-طریقہ-کار" tabindex="-1">8. معیار کی ضمانت کا طریقہ کار <a class="header-anchor" href="#_8-معیار-کی-ضمانت-کا-طریقہ-کار" aria-label="Permalink to &quot;8. معیار کی ضمانت کا طریقہ کار&quot;">​</a></h2><h3 id="_8-1-ترتیب-کے-تضاد-کی-خود-جانچ" tabindex="-1">8.1 ترتیب کے تضاد کی خود جانچ <a class="header-anchor" href="#_8-1-ترتیب-کے-تضاد-کی-خود-جانچ" aria-label="Permalink to &quot;8.1 ترتیب کے تضاد کی خود جانچ&quot;">​</a></h3><p>تمام نئی تخلیق شدہ اور ترمیم شدہ دستاویزات کو دستاویز 97《ترتیب کے تضاد کی خود جانچ کی جدول》کے تمام جانچ کے آئٹمز پاس کرنے ہوں گے، جس میں بنیادی ترتیب کی مطابقت، ماڈیولز کے درمیان منطقی مطابقت، دستاویز فارمیٹ کے ضوابط تین قسموں میں کل 40 سے زیادہ جانچ شامل ہیں۔</p><h3 id="_8-2-باہمی-تصدیق" tabindex="-1">8.2 باہمی تصدیق <a class="header-anchor" href="#_8-2-باہمی-تصدیق" aria-label="Permalink to &quot;8.2 باہمی تصدیق&quot;">​</a></h3><p>ہر دستاویز کو رسمی اشاعت سے پہلے کم از کم ایک دوسرے تخلیق کار کی باہمی تصدیق پاس کرنی ہوگی، خاص طور پر ماڈیولز کے درمیان منطقی مطابقت اور اصطلاحات کے یکجا کرنے کی جانچ کرنی ہوگی۔</p><h3 id="_8-3-صارف-کے-رائے-کا-طریقہ-کار" tabindex="-1">8.3 صارف کے رائے کا طریقہ کار <a class="header-anchor" href="#_8-3-صارف-کے-رائے-کا-طریقہ-کار" aria-label="Permalink to &quot;8.3 صارف کے رائے کا طریقہ کار&quot;">​</a></h3><p>دستاویز کے نظام میں صارف کے رائے کا چینل قائم کیا گیا ہے، جس کے ذریعے صارفین درج ذیل طریقوں سے رائے جمع کروا سکتے ہیں:</p><ul><li>ترتیب کے تضاد اور منطقی غلطیوں کی رپورٹ کرنا</li><li>اصطلاحات کی عدم یکجہتی کے مسائل اٹھانا</li><li>مخصوص مواد کی تکمیل یا ترمیم کی تجویز دینا</li><li>فارمیٹ اور متن کی غلطیوں کی نشاندہی کرنا</li></ul><p>تمام رائے ماڈیول دیکھ بھال کرنے والے کے ذریعے درجہ بندی کے ساتھ پروسیس کی جاتی ہیں، اہم رائے ترتیب دیکھ بھال کمیٹی کو غور کے لیے جمع کروائی جاتی ہیں۔</p><h3 id="_8-4-سہ-ماہی-مطابقت-کی-رپورٹ" tabindex="-1">8.4 سہ ماہی مطابقت کی رپورٹ <a class="header-anchor" href="#_8-4-سہ-ماہی-مطابقت-کی-رپورٹ" aria-label="Permalink to &quot;8.4 سہ ماہی مطابقت کی رپورٹ&quot;">​</a></h3><p>ترتیب دیکھ بھال کمیٹی ہر سہ ماہی میں ایک《ترتیب مطابقت کی رپورٹ》شائع کرتی ہے، جس کے مواد میں شامل ہیں:</p><ul><li>اس سہ ماہی میں دریافت شدہ ترتیب کے تضاد اور پروسیسنگ کی صورتحال</li><li>اس سہ ماہی میں دستاویز کی ترمیم کے اعداد و شمار</li><li>اصطلاحات کے یکجا کرنے کی پیشرفت</li><li>صارف کے رائے کی پروسیسنگ کی صورتحال</li><li>اگلے سہ ماہی کی دیکھ بھال کا منصوبہ</li></ul><h2 id="_9-دستاویز-کا-ذخیرہ-اور-تقسیم" tabindex="-1">9. دستاویز کا ذخیرہ اور تقسیم <a class="header-anchor" href="#_9-دستاویز-کا-ذخیرہ-اور-تقسیم" aria-label="Permalink to &quot;9. دستاویز کا ذخیرہ اور تقسیم&quot;">​</a></h2><h3 id="_9-1-ذخیرہ-کا-فارمیٹ" tabindex="-1">9.1 ذخیرہ کا فارمیٹ <a class="header-anchor" href="#_9-1-ذخیرہ-کا-فارمیٹ" aria-label="Permalink to &quot;9.1 ذخیرہ کا فارمیٹ&quot;">​</a></h3><p>تمام دستاویزات مارک ڈاؤن (.md) فارمیٹ میں محفوظ کی جاتی ہیں، جو کراس پلیٹ فارم پڑھنے کی اہلیت اور ورژن کے انتظام کی سہولت کو یقینی بناتی ہے۔ دستاویزات UTF-8 انکوڈنگ استعمال کرتی ہیں، چینی زبان اور خاص حروف کی حمایت کرتی ہیں۔</p><h3 id="_9-2-ڈائریکٹری-کا-ڈھانچہ" tabindex="-1">9.2 ڈائریکٹری کا ڈھانچہ <a class="header-anchor" href="#_9-2-ڈائریکٹری-کا-ڈھانچہ" aria-label="Permalink to &quot;9.2 ڈائریکٹری کا ڈھانچہ&quot;">​</a></h3><p>دستاویزات یکجا طور پر <code>anchor-docs/</code> ڈائریکٹری میں محفوظ کی جاتی ہیں، فائل نام <code>XX-دستاویز کا عنوان.md</code> فارمیٹ میں ہے۔ SPEC.md ضوابط فائل کے طور پر بھی اسی ڈائریکٹری میں محفوظ ہے۔</p><h3 id="_9-3-ورژن-کا-انتظام" tabindex="-1">9.3 ورژن کا انتظام <a class="header-anchor" href="#_9-3-ورژن-کا-انتظام" aria-label="Permalink to &quot;9.3 ورژن کا انتظام&quot;">​</a></h3><p>دستاویزات کے ورژن کے انتظام کے لیے Git جیسے ورژن کنٹرول سسٹم استعمال کرنے کی تجویز ہے، ہر بار ترمیم جمع کرواتے وقت تفصیلی commit message منسلک کرنا، ترمیم کے مواد اور وجہ ریکارڈ کرنا۔</p><h3 id="_9-4-تقسیم-کے-طریقے" tabindex="-1">9.4 تقسیم کے طریقے <a class="header-anchor" href="#_9-4-تقسیم-کے-طریقے" aria-label="Permalink to &quot;9.4 تقسیم کے طریقے&quot;">​</a></h3><p>دستاویز کا نظام درج ذیل طریقوں سے تقسیم کیا جا سکتا ہے:</p><ul><li>ZIP کمپریسڈ فائل کے طور پر پیک کرکے ڈاؤن لوڈ</li><li>اسٹیٹک ویب سائٹ کے طور پر تعینات کرکے آن لائن براؤز</li><li>PDF یا EPUB فارمیٹ میں تبدیل کرکے پڑھنا</li><li>علم خانہ سسٹم میں درآمد کرکے ساختہ انتظام</li></ul><h2 id="اختتامیہ" tabindex="-1">اختتامیہ <a class="header-anchor" href="#اختتامیہ" aria-label="Permalink to &quot;اختتامیہ&quot;">​</a></h2><p>دستاویز کا ورژن اور دیکھ بھال کی ہدایات اینکر سمبیوسس تہذیب کے ترتیب کے نظام کا &quot;انتظامی آئین&quot; ہے۔ یہ دستاویز کے نظام کے ورژن کے قواعد، دیکھ بھال کی تنظیم، ترمیم کے عمل، معیار کی ضمانت کے طریقہ کار اور ذخیرہ اور تقسیم کے طریقے قائم کرتا ہے، جو اس بات کو یقینی بناتا ہے کہ 100 دستاویزات پر مشتمل یہ وسیع ترتیب کا نظام مسلسل بڑھنے کے عمل میں ہمیشہ انتظام اور مطابقت برقرار رکھ سکے۔ ایک اچھے ترتیب کے نظام کے لیے صرف شاندار مواد کافی نہیں ہے، اس کی طویل مدتی صحت مند ترقی کو یقینی بنانے کے لیے کامل دیکھ بھال کا طریقہ کار بھی ضروری ہے۔ یہ دستاویز بالکل اسی طریقہ کار کا بنیادی وہیکل ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>97-ترتیب کے تضاد کی خود جانچ کی جدول</li><li>90-اصطلاحات کا لغت</li><li>00-ہینگیوانژو کائنات کا جائزہ</li></ul>',77)])])}const q=t(r,[["render",o]]);export{_ as __pageData,q as default};
